import { test, expect, Page } from '@playwright/test';

test.describe('Protected Page Authentication Redirect', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    // Clear all cookies and local storage to ensure unauthenticated state
    await page.context().clearCookies();
    await page.evaluate(() => {
      localStorage.clear();
      sessionStorage.clear();
    });
  });

  test('should redirect to login when accessing protected dashboard without authentication', async () => {
    // Navigate to protected page
    await page.goto('http://localhost:3000/dashboard', { waitUntil: 'networkidle' });

    // Verify redirect to login page
    expect(page.url()).toContain('/login');

    // Verify login page elements are visible
    const loginHeading = page.getByRole('heading', { name: /sign in/i });
    await expect(loginHeading).toBeVisible();

    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();

    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();

    const loginButton = page.getByRole('button', { name: /sign in|login/i });
    await expect(loginButton).toBeVisible();
  });

  test('should redirect to login when accessing protected profile page without authentication', async () => {
    // Navigate to another protected page
    await page.goto('http://localhost:3000/profile', { waitUntil: 'networkidle' });

    // Verify redirect to login page
    expect(page.url()).toContain('/login');

    // Verify we are on login page by checking for login form
    const loginForm = page.getByRole('form') || page.getByText(/sign in/i);
    await expect(loginForm).toBeDefined();
  });

  test('should redirect to login when accessing protected settings page without authentication', async () => {
    // Navigate to settings protected page
    await page.goto('http://localhost:3000/settings', { waitUntil: 'networkidle' });

    // Verify redirect to login page
    expect(page.url()).toContain('/login');

    // Verify login page is displayed
    const loginButton = page.getByRole('button', { name: /sign in|login/i });
    await expect(loginButton).toBeVisible();
  });

  test('should maintain redirect after multiple protected page access attempts', async () => {
    // Try to access first protected page
    await page.goto('http://localhost:3000/dashboard', { waitUntil: 'networkidle' });
    expect(page.url()).toContain('/login');

    // Try to access another protected page
    await page.goto('http://localhost:3000/profile', { waitUntil: 'networkidle' });
    expect(page.url()).toContain('/login');

    // Try to access yet another protected page
    await page.goto('http://localhost:3000/settings', { waitUntil: 'networkidle' });
    expect(page.url()).toContain('/login');

    // Verify login page is still accessible and functional
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();
  });

  test('should show login form with all required fields on redirect', async () => {
    // Navigate to protected page
    await page.goto('http://localhost:3000/dashboard', { waitUntil: 'networkidle' });

    // Verify all login form elements are present
    const emailLabel = page.getByLabel(/email/i);
    await expect(emailLabel).toBeVisible();

    const passwordLabel = page.getByLabel(/password/i);
    await expect(passwordLabel).toBeVisible();

    const submitButton = page.getByRole('button', { name: /sign in|login|submit/i });
    await expect(submitButton).toBeVisible();

    // Verify form is interactive
    await emailLabel.fill('test@example.com');
    await expect(emailLabel).toHaveValue('test@example.com');
  });

  test('should not allow direct access to protected page via URL manipulation', async () => {
    // Attempt to access protected page with various URL patterns
    const protectedUrls = [
      'http://localhost:3000/dashboard',
      'http://localhost:3000/dashboard/',
      'http://localhost:3000/dashboard?redirect=true',
    ];

    for (const url of protectedUrls) {
      await page.goto(url, { waitUntil: 'networkidle' });
      // All should redirect to login
      expect(page.url()).toContain('/login');
    }
  });
});
